WITH lines AS (SELECT id, effective_from, currency, EXPLODE_OUTER(discounts) AS tier_value FROM price_tiers), scored AS (SELECT *, PERCENT_RANK() OVER w_running AS tier_value_percent_rank, MAX(tier_value) OVER (PARTITION BY currency) AS currency_max_tier_value FROM lines WINDOW w_running AS (PARTITION BY MONTH(effective_from) ORDER BY tier_value ASC)), base AS (SELECT *, CEIL(tier_value) AS tier_value_whole FROM scored WHERE effective_from >= DATE '2024-03-06'), cleaned AS (SELECT *, GREATEST(tier_value, tier_value_percent_rank) AS greatest_tier_value_tier_value_percent_rank, COALESCE(currency_max_tier_value, 0) AS currency_max_tier_value_filled FROM base WHERE effective_from > DATE '2024-02-28'), cleaned_price_tiers AS (SELECT *, ROUND(currency_max_tier_value_filled, 0) AS currency_max_tier_value_filled_rounded FROM cleaned WHERE effective_from > DATE '2024-03-15' AND tier_value_whole = 51), summary AS (SELECT CASE WHEN tier_value_whole >= 88 THEN 'PREMIUM' ELSE 'STANDARD' END AS tier_value_whole_tier, COUNT(DISTINCT currency) AS distinct_currencies, SIZE(COLLECT_SET(currency)) AS num_currencies FROM cleaned_price_tiers GROUP BY tier_value_whole_tier HAVING SIZE(COLLECT_SET(currency)) < 1000) SELECT tier_value_whole_tier FROM summary ORDER BY tier_value_whole_tier DESC;
